// Service worker registration (generated by vite-plugin-pwa, autoUpdate) and
// recovery from stale lazy chunks after a deploy.

type Listener = () => void;
const updateListeners = new Set<Listener>();
let updateReady = false;

export function onUpdateReady(l: Listener): () => void {
  updateListeners.add(l);
  if (updateReady) l();
  return () => updateListeners.delete(l);
}

export function isUpdateReady() {
  return updateReady;
}

/** Reloading in the middle of an inspection is safe (state is in Dexie), but don't surprise the soldier. */
function safeToReload(): boolean {
  return !window.location.pathname.startsWith('/session/');
}

export function registerServiceWorker() {
  if (!import.meta.env.PROD || !('serviceWorker' in navigator)) return;
  const hadController = !!navigator.serviceWorker.controller;
  let reloading = false;

  navigator.serviceWorker.addEventListener('controllerchange', () => {
    if (!hadController || reloading) return; // first install: nothing to refresh
    if (safeToReload()) {
      reloading = true;
      window.location.reload();
    } else {
      updateReady = true;
      updateListeners.forEach((l) => l());
    }
  });

  window.addEventListener('load', () => {
    navigator.serviceWorker
      .register('/sw.js', { scope: '/' })
      .then((reg) => {
        setInterval(() => reg.update().catch(() => undefined), 60 * 60 * 1000);
      })
      .catch((err) => console.warn('Service worker registration failed:', err));
  });
}

const PRELOAD_RELOAD_KEY = 'pmcs_preload_reload_at';

/** A lazy chunk from an old deploy is gone: reload once to pick up the new build. */
export function installPreloadErrorHandler() {
  window.addEventListener('vite:preloadError', (event) => {
    let last = 0;
    try {
      last = Number(sessionStorage.getItem(PRELOAD_RELOAD_KEY) || 0);
    } catch {
      last = 0;
    }
    if (Date.now() - last < 10_000) return; // avoid reload loops
    event.preventDefault();
    try {
      sessionStorage.setItem(PRELOAD_RELOAD_KEY, String(Date.now()));
    } catch {
      // ignore
    }
    window.location.reload();
  });
}
